import 'dart:convert';

import 'lock.dart';
import 'manifest.dart';

/// The folder in the app that holds the vendored plugins, one folder per id,
/// and the generated file.
const pluginsDir = 'lib/devpul';

/// The generated file, relative to the app root.
const generatedFile = '$pluginsDir/plugins.dart';

/// The generated file for [lock]. [vendored] holds each plugin's files by id,
/// then by path, `plugin.json` included.
String render(Lock lock, Map<String, Map<String, String>> vendored) {
  final plugins = [
    for (final MapEntry(key: id, value: entry) in lock.plugins.entries)
      (id: id, entry: entry, manifest: _manifest(id, entry, vendored[id])),
  ];
  final out = StringBuffer(
    '// Generated by devpul from devpul.lock. Do not edit.\n',
  );
  for (final (:id, :entry, :manifest) in plugins) {
    out.write('//\n// $id ${entry.version} from ${entry.url}\n');
    for (final line in manifest.usage) {
      out.write('//   $line\n');
    }
  }
  out.write('''

// dart format off
// ignore_for_file: type=lint
''');
  if (plugins.any((p) => p.manifest.source != null)) {
    out.write("\nimport 'package:devpul/devpul.dart';\n");
  }
  final exports = [
    for (final (:id, entry: _, :manifest) in plugins)
      if (manifest.dart case final dart?) "export '$id/$dart';",
  ];
  if (exports.isNotEmpty) out.write('\n${exports.join('\n')}\n');
  out.write('''

const _debug =
    !bool.fromEnvironment('dart.vm.product') &&
    !bool.fromEnvironment('dart.vm.profile');

/// Offers the plugins in devpul.lock to DevPul in debug builds. Release and
/// profile builds leave them out.
abstract final class DevpulPlugins {
  static void install() {
    if (!_debug) return;
''');
  for (final (:id, :entry, :manifest) in plugins) {
    final source = module(manifest, vendored[id]!);
    if (source == null) continue;
    out.write('''
    Devpul.plugin(
      ${_string(id)},
      () => ${multiline(source)},
      version: ${_string('${entry.version}')},
      origin: ${_string(entry.url)},
      description: ${_string(manifest.description)},
    );
''');
  }
  out.write('  }\n}\n');
  return out.toString();
}

/// The module the UI runs: the source with the icon appended as an `icon`
/// export. Null for a plugin with no source.
String? module(Manifest manifest, Map<String, String> files) {
  final path = manifest.source;
  if (path == null) return null;
  var source = normalizeNewlines(files[path]!);
  if (manifest.icon case final icon?) {
    if (!source.endsWith('\n')) source += '\n';
    final svg = normalizeNewlines(files[icon]!).trim();
    source += 'export const icon = ${jsonEncode(svg)};\n';
  }
  return source;
}

Manifest _manifest(String id, LockEntry entry, Map<String, String>? files) {
  final text = files?['plugin.json'];
  if (text == null) throw StateError('$pluginsDir/$id/plugin.json is missing');
  final Manifest manifest;
  try {
    manifest = Manifest.parse(jsonDecode(text));
  } on FormatException catch (e) {
    throw StateError('$pluginsDir/$id/plugin.json: ${e.message}');
  } on ManifestException catch (e) {
    throw StateError('$pluginsDir/$id/$e');
  }
  if (manifest.id != id || manifest.version != entry.version) {
    throw StateError(
      '$pluginsDir/$id/plugin.json is ${manifest.id} ${manifest.version}; '
      'devpul.lock has $id ${entry.version}',
    );
  }
  for (final path in manifest.files) {
    if (!files!.containsKey(path)) {
      throw StateError('$pluginsDir/$id/$path is missing');
    }
  }
  return manifest;
}

String _string(String text) =>
    "'${text.replaceAll(r'\', r'\\').replaceAll("'", r"\'").replaceAll(r'$', r'\$').replaceAll('\n', r'\n')}'";

/// A Dart string literal for [text], raw where it can be. The newline after
/// the opening quotes is not part of the string.
String multiline(String text) {
  for (final quote in ["'''", '"""']) {
    if (!text.contains(quote) && !text.endsWith(quote[0])) {
      return 'r$quote\n$text$quote';
    }
  }
  final escaped = text
      .replaceAll(r'\', r'\\')
      .replaceAll(r'$', r'\$')
      .replaceAll("'", r"\'");
  return "'''\n$escaped'''";
}
